import React, { useContext } from 'react';
import { FormattedMessage } from 'react-intl';
import styled from 'styled-components';

import Colors from '@dynatrace/strato-design-tokens/colors';
import Spacings from '@dynatrace/strato-design-tokens/spacings';
import Typography from '@dynatrace/strato-design-tokens/typography';

import type { WithChildren } from '../../core/types/with-children.js';
import { Flex } from '../../layouts-core/flex/Flex.js';
import { Text } from '../../typography/Text.js';
import { DataTableContext } from '../contexts/DataTableContext.js';

//#region Typings
export type SelectionChipProps = WithChildren;
//#endregion Typings

// #region StyledComponents
const StyledChipWrapper = /* @__PURE__ */ styled(Flex)({
  padding: `${Spacings.Size6} ${Spacings.Size8}`,
  marginLeft: Spacings.Size2,
  alignItems: 'flex-end',
  justifyContent: 'flex-end',
});

const StyledChip = /* @__PURE__ */ styled(Flex)({
  height: Spacings.Size20,
  minWidth: Spacings.Size12,
  padding: `${Spacings.Size0} ${Spacings.Size4}`,
  justifyContent: 'center',
  alignItems: 'center',
  background: Colors.Background.Field.Primary.Accent,
  color: Colors.Background.Base.Default,
  borderRadius: Spacings.Size4,
  fontSize: Typography.Text.Base.Default.Size,
});
// #endregion

export const SelectionChip = (props: SelectionChipProps) => {
  const { currentSelectedRows } = useContext(DataTableContext);
  const rowsCount = currentSelectedRows.length;
  return (
    <StyledChipWrapper>
      <StyledChip>{rowsCount}</StyledChip>
      <Text as="p" textStyle="base">
        {props.children ? (
          props.children
        ) : (
          <FormattedMessage
            defaultMessage="selected"
            id="xFQW8ah15nm5hjiI"
            description="Message to display for the total count of selected rows."
          />
        )}
      </Text>
    </StyledChipWrapper>
  );
};

SelectionChip['displayName'] = 'DataTable.SelectionChip';
